import assert from "node:assert/strict";
import { test } from "node:test";
import { run } from "../src/cli.js";
import { createStore } from "../src/store.js";

test("rename replies 'Renamed <id>: <new title>' and the list shows the new title afterwards", () => {
  const store = createStore();
  store.add("Buy milk");
  store.add("Call Sam");
  assert.equal(
    run(["rename", "2", "Call", "Sam", "back"], store),
    "Renamed 2: Call Sam back"
  );
  assert.equal(store.all().find((t) => t.id === 2).title, "Call Sam back");
  assert.equal(run(["list"], store), "[ ] 1 Buy milk\n[ ] 2 Call Sam back");
});

test("a renamed task keeps its id, its done state and its place in the list", () => {
  const store = createStore();
  run(["add", "Buy milk"], store);
  run(["add", "Call Sam"], store);
  run(["add", "Walk dog"], store);
  run(["done", "2"], store);
  assert.equal(
    run(["rename", "2", "Call Sam back"], store),
    "Renamed 2: Call Sam back"
  );
  assert.equal(
    run(["list"], store),
    "[ ] 1 Buy milk\n[x] 2 Call Sam back\n[ ] 3 Walk dog"
  );
});

test("the new title is the whole text after the id, spaces and commas included", () => {
  const store = createStore();
  store.add("one");
  store.add("two");
  store.add("three");
  assert.equal(
    run(["rename", "3", "Buy milk, eggs, and bread"], store),
    "Renamed 3: Buy milk, eggs, and bread"
  );
  assert.equal(
    store.all().find((t) => t.id === 3).title,
    "Buy milk, eggs, and bread"
  );
  assert.equal(
    run(["rename", "2", "Buy", "milk,", "eggs,", "and", "bread"], store),
    "Renamed 2: Buy milk, eggs, and bread"
  );
  assert.equal(
    store.all().find((t) => t.id === 2).title,
    "Buy milk, eggs, and bread"
  );
});

test("rename trims the new title exactly like add trims a task title", () => {
  const store = createStore();
  store.add("Buy milk");
  store.add("Call Sam");
  assert.equal(
    run(["rename", "2", "  Call Sam back  "], store),
    "Renamed 2: Call Sam back"
  );
  const added = store.add("  Call Sam back  ");
  assert.equal(store.all().find((t) => t.id === 2).title, "Call Sam back");
  assert.equal(added.title, store.all().find((t) => t.id === 2).title);
});

test("rename with a missing or blank new title reports an error and leaves the task exactly as it was", () => {
  const store = createStore();
  store.add("Buy milk");
  store.add("Call Sam");
  store.complete(2);
  assert.throws(() => run(["rename", "2"], store), /needs a title/);
  assert.throws(() => run(["rename", "2", "   "], store), /needs a title/);
  assert.deepEqual(store.all(), [
    { id: 1, title: "Buy milk", done: false },
    { id: 2, title: "Call Sam", done: true },
  ]);
});

test("rename of an id no task has replies 'No task with id <id>' and changes nothing", () => {
  const store = createStore();
  store.add("Buy milk");
  store.add("Call Sam");
  assert.throws(
    () => run(["rename", "7", "Call", "Sam", "back"], store),
    /^No task with id 7$/
  );
  assert.deepEqual(store.all(), [
    { id: 1, title: "Buy milk", done: false },
    { id: 2, title: "Call Sam", done: false },
  ]);
});

test("rename whose first argument is not a task id replies 'Not a task id: <argument>' and changes nothing", () => {
  const store = createStore();
  store.add("Buy milk");
  assert.throws(
    () => run(["rename", "abc", "Call", "Sam"], store),
    /^Not a task id: abc$/
  );
  assert.deepEqual(store.all(), [{ id: 1, title: "Buy milk", done: false }]);
});

test("rename with no arguments at all reports an error and changes nothing", () => {
  const store = createStore();
  store.add("Buy milk");
  assert.throws(() => run(["rename"], store), /Not a task id/);
  assert.deepEqual(store.all(), [{ id: 1, title: "Buy milk", done: false }]);
});

test("add, done, remove and list keep their exact replies and effects", () => {
  const store = createStore();
  assert.equal(run(["add", "Buy", "milk"], store), "Added 1: Buy milk");
  assert.equal(run(["add", "Call Sam"], store), "Added 2: Call Sam");
  assert.equal(run(["done", "1"], store), "Completed 1");
  assert.equal(run(["list"], store), "[x] 1 Buy milk\n[ ] 2 Call Sam");
  assert.throws(() => run(["add", "   "], store), /needs a title/);
  assert.equal(run(["add", "Walk dog"], store), "Added 3: Walk dog");
  assert.equal(run(["remove", "2"], store), "Removed 2");
  assert.equal(run(["list"], store), "[x] 1 Buy milk\n[ ] 3 Walk dog");
  assert.equal(run(["list"], createStore()), "No tasks.");
  assert.throws(() => run(["done", "abc"], store), /^Not a task id: abc$/);
  assert.throws(() => run(["done", "7"], store), /^No task with id 7$/);
  assert.throws(() => run(["remove", "7"], store), /^No task with id 7$/);
  assert.throws(() => run(["explode"], store), /^Unknown command: explode$/);
});

