  const store = createStore();
  assert.equal(run(["add", "Buy milk"], store), "Added 1: Buy milk");
  assert.equal(
    run(["rename", "1", "Buy oat milk"], store),
    "Renamed 1: Buy oat milk"
  );
  assert.equal(run(["add", "Call Sam"], store), "Added 2: Call Sam");
  assert.equal(run(["done", "1"], store), "Completed 1");
  assert.equal(run(["list"], store), "[x] 1 Buy oat milk\n[ ] 2 Call Sam");
  assert.equal(run(["remove", "2"], store), "Removed 2");
  assert.equal(run(["list"], store), "[x] 1 Buy oat milk");
  assert.equal(store.add("Walk dog").id, 3);
});

